package rules; import java.util.List;import java.util.Map;import java.util.TreeMap; public final class RuleSummary{public String summarize(List<IdsRule> rules){Map<String,Integer>actions=new TreeMap<>();Map<String,Integer>protocols=new TreeMap<>();if(rules!=null)for(IdsRule r:rules){actions.merge(r.action(),1,Integer::sum);protocols.merge(r.protocol(),1,Integer::sum);}return"rules="+(rules==null?0:rules.size())+" actions="+actions+" protocols="+protocols;}}
